<?php
namespace App\Domains\Api\Http\Controllers;
use App\Domains\Api\Models\{ApiCatalogEntry,ApiClient,ApiKey}; use App\Domains\Api\Support\ApiResponse; use App\Domains\Platform\Contracts\TenantContext; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Str;
class ApiGovernanceController { public function __construct(private readonly TenantContext $tenant){} private function allow(Request $r,string $p):void{$r->user()->hasPermission($p)||abort(403);} public function catalog(Request $r):JsonResponse{$this->allow($r,'api.view');return ApiResponse::success(ApiCatalogEntry::query()->where('status','active')->when($r->query('version'),fn($q,$v)=>$q->where('version',$v))->get());} public function clients(Request $r):JsonResponse{$this->allow($r,'api.manage');return ApiResponse::success(ApiClient::query()->where('tenant_id',$this->tenant->id())->with('keys')->paginate(25));} public function createClient(Request $r):JsonResponse{$this->allow($r,'api.manage');$d=$r->validate(['name'=>['required','string','max:160'],'client_type'=>['required','in:partner,internal,mobile,service_account'],'scopes'=>['nullable','array']]);$client=ApiClient::query()->create([...$d,'tenant_id'=>$this->tenant->id()]);$plain='fep_'.Str::random(48);$client->keys()->create(['key_hash'=>hash('sha512',$plain),'label'=>'default']);return ApiResponse::success([...$client->toArray(),'api_key'=>$plain],[],[])->setStatusCode(201);} public function revoke(Request $r,string $client):JsonResponse{$this->allow($r,'api.manage');$model=ApiClient::query()->where('tenant_id',$this->tenant->id())->findOrFail($client);$model->update(['status'=>'revoked']);$model->keys()->update(['status'=>'revoked']);return ApiResponse::success($model);} }
